/*
    Parallel sum reduction using shared memory
    - takes log(n) steps for n input elements
    - uses n threads
    - only works for power-of-2 arrays
*/

/* This reduction interleaves which threads are active by using the modulo
   operator.  This operator is very expensive on GPUs, and the interleaved
   inactivity means that no whole warps are active, which is also very
   inefficient */
template <class T> __global__ void reduce0(T *g_idata, T *g_odata, unsigned int n)
{
    // Handle to thread block group
    cg::thread_block cta   = cg::this_thread_block();
    T               *sdata = SharedMemory<T>();

    // load shared mem
    unsigned int tid = threadIdx.x;
    unsigned int i   = blockIdx.x * blockDim.x + threadIdx.x;

    sdata[tid] = (i < n) ? g_idata[i] : 0;

    cg::sync(cta);

    // do reduction in shared mem
    for (unsigned int s = 1; s < blockDim.x; s *= 2) {
        // modulo arithmetic is slow!
        if ((tid % (2 * s)) == 0) {
            sdata[tid] += sdata[tid + s];
        }

        cg::sync(cta);
    }

    // write result for this block to global mem
    if (tid == 0)
        g_odata[blockIdx.x] = sdata[0];
}

// Large-input first stage: each CTA covers 1024 inputs while retaining the
// same 128-thread shared-memory reduction used by reduce0.
template <class T> __global__ void reduce0_large(T *g_idata, T *g_odata, unsigned int n)
{
    cg::thread_block cta   = cg::this_thread_block();
    T               *sdata = SharedMemory<T>();

    unsigned int tid  = threadIdx.x;
    unsigned int base = blockIdx.x * (blockDim.x * 8u) + tid;
    T sum = 0;

    #pragma unroll
    for (unsigned int item = 0; item < 8; ++item) {
        unsigned int i = base + item * blockDim.x;
        if (i < n)
            sum += g_idata[i];
    }
    sdata[tid] = sum;

    cg::sync(cta);

    for (unsigned int s = 1; s < blockDim.x; s *= 2) {
        if ((tid % (2 * s)) == 0) {
            sdata[tid] += sdata[tid + s];
        }
        cg::sync(cta);
    }

    if (tid == 0)
        g_odata[blockIdx.x] = sdata[0];
}

// The final CTA reduces all first-stage partials and writes directly to out.
__global__ void reduce_final(int *partials, int *out, unsigned int n)
{
    cg::thread_block cta   = cg::this_thread_block();
    int             *sdata = SharedMemory<int>();
    unsigned int tid = threadIdx.x;
    int sum = 0;

    for (unsigned int i = tid; i < n; i += blockDim.x)
        sum += partials[i];
    sdata[tid] = sum;

    cg::sync(cta);

    for (unsigned int s = 1; s < blockDim.x; s *= 2) {
        if ((tid % (2 * s)) == 0) {
            sdata[tid] += sdata[tid + s];
        }
        cg::sync(cta);
    }

    if (tid == 0)
        *out = sdata[0];
}

#endif
extern "C" void run(const void *x, const void *k, const void *gy, void *out,
                    void *scratch, int n, int h, int l, int ks)
{
    if (n > 32768) {
        unsigned int blocks = (static_cast<unsigned int>(n) + 1023u) / 1024u;
        int *partials = static_cast<int *>(scratch);
        reduce0_large<int><<<blocks, 128, 128 * sizeof(int)>>>(
            static_cast<int *>(const_cast<void *>(x)), partials,
            static_cast<unsigned int>(n));
        reduce_final<<<1, 128, 128 * sizeof(int)>>>(partials,
            static_cast<int *>(out), blocks);
        return;
    }

    int count = n;
    int *input = static_cast<int *>(const_cast<void *>(x));
    bool flip = false;
    while (count > 1) {
        int blocks = (count + 128 - 1) / 128;
        int *dest = flip ? static_cast<int *>(scratch) + n + 32768
                         : static_cast<int *>(scratch);
        reduce0<int><<<blocks, 128, 128 * sizeof(int)>>>(input, dest, count);
        input = dest;
        count = blocks;
        flip = !flip;
    }
    cudaMemcpyAsync(out, input, sizeof(int), cudaMemcpyDeviceToDevice);
}

